'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import ProductImage from '@/components/product-image'
import { 
  ArrowLeft, 
  Check, 
  CreditCard, 
  MapPin, 
  Truck, 
  Shield, 
  User,
  Phone,
  Mail,
  Lock,
  Package
} from 'lucide-react'
import Header from '@/components/header'
import Footer from '@/components/footer'
import { refreshCartPrices } from '@/lib/cart'
import { clearAppliedCouponCode, getAppliedCouponCode, setAppliedCouponCode } from '@/lib/coupon-storage'
import { formatTRY, toDisplayPrice } from '@/lib/price'
import { calculateCheckoutTotals, FREE_SHIPPING_THRESHOLD_KURUS } from '@/lib/checkout-pricing'
import { adItemsFromCart, adValueFromCart } from '@/lib/analytics/value'
import { trackAddPaymentInfo, trackInitiateCheckout } from '@/lib/analytics/datalayer'
import { getCheckoutTrackingPayload } from '@/lib/analytics/tracking'
import { useConsentedTracking } from '@/lib/analytics/use-consented-tracking'

type Step = 'info' | 'shipping' | 'payment'

type CartItem = {
  id: string
  slug: string
  name: string
  image: string
  price: number
  qty: number
}

export default function CheckoutPage() {
  const router = useRouter()
  const [currentStep, setCurrentStep] = useState<Step>('info')
  const [cartItems, setCartItems] = useState<CartItem[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [pricesVerified, setPricesVerified] = useState(false)
  const [isProcessing, setIsProcessing] = useState(false)
  const [paymentUncertain, setPaymentUncertain] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [couponCode, setCouponCode] = useState('')
  const [validatedCouponCode, setValidatedCouponCode] = useState('')
  const [couponDiscount, setCouponDiscount] = useState(0)
  const [couponError, setCouponError] = useState<string | null>(null)
  const [isApplyingCoupon, setIsApplyingCoupon] = useState(false)
  
  const [formData, setFormData] = useState({
    // Müşteri Bilgileri
    name: '',
    surname: '',
    email: '',
    phone: '',
    tc: '',
    
    // Adres Bilgileri
    address: '',
    city: '',
    district: '',
    zipCode: '',
    
    // Kargo Seçimi
    shippingMethod: 'standard',
    
    // Ödeme Bilgileri
    cardNumber: '',
    cardName: '',
    expireMonth: '',
    expireYear: '',
    cvc: '',
    
    // Sözleşmeler
    termsAccepted: false,
    kvkkAccepted: false,
  })

  // Each newly permitted channel receives the current checkout once.
  useConsentedTracking('checkout', (channels) => {
    if (isLoading || cartItems.length === 0) return false
    const contents = adItemsFromCart(cartItems)
    const value = adValueFromCart(cartItems)
    return trackInitiateCheckout({
        value,
        contents,
        items: contents.map((c) => ({
          item_id: c.id,
          quantity: c.quantity,
          price: c.item_price,
        })),
      ...channels,
    })
  })

  // Load cart and user profile
  useEffect(() => {
    const loadData = async () => {
      try {
        // Load cart
        const cart = await refreshCartPrices()
        setCartItems(cart)
        setPricesVerified(true)
        const storedCoupon = getAppliedCouponCode()
        if (storedCoupon) setCouponCode(storedCoupon)

        // A profile lookup failure must not invalidate a successful price quote.
        const result = await fetch('/api/auth/me').then(response => response.json()).catch(() => null)
        
        if (result?.success && result.user) {
          const fullName = result.user.name || ''
          const nameParts = fullName.split(' ')
          const firstName = nameParts[0] || ''
          const lastName = nameParts.slice(1).join(' ') || ''
          
          setFormData(prev => ({
            ...prev,
            name: firstName,
            surname: lastName,
            email: result.user.email || '',
            phone: result.user.phone || ''
          }))
        }
        if (storedCoupon) await applyCoupon(storedCoupon, result?.user?.email || '')
      } catch (error) {
        console.error('Error loading data:', error)
        setError('Güncel ürün fiyatları doğrulanamadı. Ödeme için lütfen sepeti yenileyin.')
      } finally {
        setIsLoading(false)
      }
    }
    
    loadData()
  }, [])

  // Calculations
  const subtotal = cartItems.reduce((sum, item) => sum + (item.price * item.qty), 0)
  const totals = calculateCheckoutTotals(subtotal, couponDiscount)
  const subtotalAfterCoupon = totals.subtotalAfterDiscountKurus
  const shipping = totals.shippingKurus
  const total = totals.totalKurus

  const applyCoupon = async (restoredCode?: string, restoredEmail?: string) => {
    const codeToApply = (restoredCode ?? couponCode).trim().toUpperCase()
    if (!codeToApply) {
      setCouponError('Lütfen kupon kodu girin')
      setCouponDiscount(0)
      setValidatedCouponCode('')
      clearAppliedCouponCode()
      return
    }
    try {
      setIsApplyingCoupon(true)
      setCouponError(null)
      const refreshedCart = await refreshCartPrices()
      setCartItems(refreshedCart)
      setPricesVerified(true)
      setError(null)
      const response = await fetch('/api/coupons/validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          couponCode: codeToApply,
          email: restoredEmail ?? (formData.email || ''),
          items: refreshedCart.map(item => ({ id: item.id, quantity: item.qty })),
        }),
      })
      const result = await response.json()
      if (!result.success) {
        setCouponDiscount(0)
        setValidatedCouponCode('')
        setCouponError(result.error || 'Kupon uygulanamadı')
        clearAppliedCouponCode()
        return
      }
      const refreshedSubtotal = refreshedCart.reduce((sum, item) => sum + item.price * item.qty, 0)
      if (result.data.subtotalKurus !== refreshedSubtotal) throw new Error('Basket quote changed during coupon validation')
      const amount = result.data.discountAmountKurus
      if (!Number.isSafeInteger(amount) || amount < 0 || amount > refreshedSubtotal) throw new Error('Invalid coupon amount')
      setCouponDiscount(amount)
      setValidatedCouponCode(codeToApply)
      setAppliedCouponCode(codeToApply)
    } catch {
      setCouponDiscount(0)
      setValidatedCouponCode('')
      setPricesVerified(false)
      setError('Güncel ürün fiyatları doğrulanamadı. Ödeme için lütfen sepeti yenileyin.')
      setCouponError('Kupon doğrulanırken hata oluştu')
      clearAppliedCouponCode()
    } finally {
      setIsApplyingCoupon(false)
    }
  }

  // Validation
  const validateStep = (step: Step): boolean => {
    setError(null)
    
    if (step === 'info') {
      if (!formData.name || !formData.surname || !formData.email || !formData.phone) {
        setError('Lütfen tüm kişisel bilgileri doldurun')
        return false
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
        setError('Geçerli bir e-posta adresi girin')
        return false
      }
      if (!/^[0-9]{10,11}$/.test(formData.phone.replace(/\s/g, ''))) {
        setError('Geçerli bir telefon numarası girin')
        return false
      }
      const tc = (formData.tc || '').replace(/\s/g, '')
      if (!tc || tc.length !== 11 || !/^[0-9]{11}$/.test(tc)) {
        setError('Geçerli 11 haneli TC Kimlik No girin (iyzico güvenli ödeme sistemi için zorunludur)')
        return false
      }
      return true
    }
    
    if (step === 'shipping') {
      if (!formData.address || !formData.city || !formData.district) {
        setError('Lütfen tüm adres bilgilerini doldurun')
        return false
      }
      return true
    }
    
    return true
  }

  const handleNextStep = () => {
    if (currentStep === 'info' && validateStep('info')) {
      setCurrentStep('shipping')
      window.scrollTo({ top: 0, behavior: 'smooth' })
    } else if (currentStep === 'shipping' && validateStep('shipping')) {
      setCurrentStep('payment')
      window.scrollTo({ top: 0, behavior: 'smooth' })
    }
  }

  const handlePreviousStep = () => {
    setError(null)
    if (currentStep === 'payment') {
      setCurrentStep('shipping')
    } else if (currentStep === 'shipping') {
      setCurrentStep('info')
    }
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }

  const handlePayment = async () => {
    if (paymentUncertain || isProcessing || isApplyingCoupon) return
    if (isLoading || !pricesVerified || cartItems.length === 0) {
      setError('Güncel ürün fiyatları doğrulanamadı. Ödeme için lütfen sepeti yenileyin.')
      return
    }
    if (!formData.termsAccepted || !formData.kvkkAccepted) {
      setError('Lütfen sözleşmeleri kabul edin')
      return
    }

    setIsProcessing(true)
    setError(null)
    let handedOffToThreeDS = false

    try {
      // AddPaymentInfo — document.write 3DS devrinden ÖNCE (sonra JS bağlamı yok)
      const contents = adItemsFromCart(cartItems)
      const value = adValueFromCart(cartItems)
      trackAddPaymentInfo({
        value,
        contents,
        items: contents.map((c) => ({
          item_id: c.id,
          quantity: c.quantity,
          price: c.item_price,
        })),
      })

      const tracking = getCheckoutTrackingPayload()

      const response = await fetch('/api/payment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          expectedTotalKurus: total,
          items: cartItems.map(item => ({
            id: item.id,
            name: item.name,
            category: 'Kozmetik',
            quantity: item.qty
          })),
          couponCode: validatedCouponCode,
          tracking,
          customerInfo: {
            name: formData.name,
            surname: formData.surname,
            email: formData.email,
            phone: formData.phone,
            tc: formData.tc,
            address: formData.address,
            city: formData.city,
            zipCode: formData.zipCode,
            cardNumber: formData.cardNumber,
            cardName: formData.cardName,
            expireMonth: formData.expireMonth,
            expireYear: formData.expireYear,
            cvc: formData.cvc
          }
        })
      })

      const result = await response.json()
      
      if (result.status === 'pending' && result.conversationId) {
        setPaymentUncertain(true)
        const params = new URLSearchParams({ token: result.conversationId, status: 'pending' })
        if (result.orderNumber) params.set('orderNumber', result.orderNumber)
        window.location.href = `/payment/callback?${params}`
        return
      }
      if (result.success) {
        if (result.requires3DS && result.threeDSHtmlContent) {
          const raw = String(result.threeDSHtmlContent || '')
          let html = raw
          // Iyzico bazen 3DS içeriğini base64 gönderir.
          if (!raw.includes('<html') && !raw.includes('<form')) {
            try {
              html = decodeURIComponent(escape(window.atob(raw)))
            } catch {
              html = raw
            }
          }
          // Aynı sekmede tam sayfa 3DS: bankanın kendi akışı (OTP sonrası bankada “onay” ekranı
          // gösterilip gösterilmemesi tamamen bankaya bağlı; yeni sekme bu hissi bozabiliyordu).
          handedOffToThreeDS = true
          setIsProcessing(false)
          document.open()
          document.write(html)
          document.close()
          return
        } else if (result.paymentPageUrl) {
          window.location.href = result.paymentPageUrl
        }
      } else {
        setError(result.error || 'Ödeme işlemi başlatılamadı')
      }
    } catch (err: any) {
      setPaymentUncertain(true)
      setError('Ödeme sonucu doğrulanamadı. Lütfen yeniden ödeme yapmayın; sipariş durumunu kontrol edin veya bizimle iletişime geçin.')
      console.error('Payment error:', err)
    } finally {
      if (!handedOffToThreeDS) {
        setIsProcessing(false)
      }
    }
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50">
        <Header />
        <div className="container py-20 flex items-center justify-center">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900 mx-auto"></div>
            <p className="mt-4 text-gray-600">Yükleniyor...</p>
          </div>
        </div>
        <Footer />
      </div>
    )
  }

  if (cartItems.length === 0) {
  return (
      <div className="min-h-screen bg-gray-50">
        <Header />
        <div className="container py-20">
          <div className="max-w-md mx-auto text-center">
            <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h1 className="text-2xl font-bold text-gray-900 mb-2">Sepetiniz Boş</h1>
            {error && <p role="alert" className="mb-4 text-red-600">{error}</p>}
            <p className="text-gray-600 mb-6">Ödeme yapabilmek için sepetinize ürün eklemelisiniz.</p>
            <Link
              href="/tum-urunler"
              className="inline-block px-6 py-3 bg-black text-white rounded-lg hover:bg-gray-800 transition-colors"
            >
              Alışverişe Başla
            </Link>
          </div>
        </div>
        <Footer />
      </div>
    )
  }

  const steps = [
    { id: 'info', label: 'Bilgileriniz', icon: User },
    { id: 'shipping', label: 'Teslimat', icon: Truck },
    { id: 'payment', label: 'Ödeme', icon: CreditCard },
  ]

  const currentStepIndex = steps.findIndex(s => s.id === currentStep)

  return (
    <div className="min-h-screen bg-gray-50">
      <Header />

      {/* Breadcrumb */}
      <nav className="bg-white border-b border-gray-200 py-3">
        <div className="container">
          <div className="flex items-center gap-2 text-sm text-gray-600">
            <Link href="/" className="hover:text-black">Anasayfa</Link>
            <span>/</span>
            <Link href="/sepet" className="hover:text-black">Sepet</Link>
            <span>/</span>
            <span className="text-black font-medium">Ödeme</span>
          </div>
        </div>
      </nav>

      <div className="container py-8 lg:py-12">
        {/* Progress Steps */}
        <div className="max-w-3xl mx-auto mb-8 lg:mb-12">
          <div className="flex items-center justify-between">
            {steps.map((step, index) => {
              const StepIcon = step.icon
              const isActive = step.id === currentStep
              const isCompleted = index < currentStepIndex

  return (
                <div key={step.id} className="flex items-center flex-1">
                  <div className="flex flex-col items-center flex-1">
                    <div
                      className={`w-10 h-10 lg:w-12 lg:h-12 rounded-full flex items-center justify-center transition-all duration-300 ${
                        isCompleted
                          ? 'bg-green-500 text-white'
                          : isActive
                          ? 'bg-black text-white scale-110'
                          : 'bg-gray-200 text-gray-400'
                      }`}
                    >
                      {isCompleted ? (
                        <Check className="w-5 h-5 lg:w-6 lg:h-6" />
                      ) : (
                        <StepIcon className="w-5 h-5 lg:w-6 lg:h-6" />
                      )}
                    </div>
                    <span
                      className={`mt-2 text-xs lg:text-sm font-medium ${
                        isActive ? 'text-black' : 'text-gray-500'
                      }`}
                    >
                      {step.label}
                    </span>
                  </div>
                  {index < steps.length - 1 && (
                    <div
                      className={`h-0.5 flex-1 mx-2 lg:mx-4 transition-all duration-300 ${
                        index < currentStepIndex ? 'bg-green-500' : 'bg-gray-200'
                      }`}
                    />
                  )}
            </div>
              )
            })}
          </div>
          </div>
          
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2">
            <div className="bg-white rounded-xl shadow-sm p-6 lg:p-8">
              {/* Error Message */}
              {error && (
                <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm">
                  {error}
                </div>
              )}

              {/* Step: Info */}
              {currentStep === 'info' && (
                <div className="space-y-6">
                  <div>
                    <h2 className="text-2xl font-bold text-black mb-2">Kişisel Bilgiler</h2>
                    <p className="text-gray-600 text-sm">Fatura ve iletişim bilgilerinizi girin</p>
            </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        Ad <span className="text-red-500">*</span>
                      </label>
                      <div className="relative">
                        <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                        <input
                          type="text"
                          value={formData.name}
                          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                          className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                          placeholder="Adınız"
                          required
                        />
          </div>
        </div>

        <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        Soyad <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        value={formData.surname}
                        onChange={(e) => setFormData({ ...formData, surname: e.target.value })}
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="Soyadınız"
                        required
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      E-posta <span className="text-red-500">*</span>
                    </label>
                    <div className="relative">
                      <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                      <input
                        type="email"
                        value={formData.email}
                        onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                        className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="ornek@email.com"
                        required
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Telefon <span className="text-red-500">*</span>
                    </label>
                    <div className="relative">
                      <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                      <input
                        type="tel"
                        value={formData.phone}
                        onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                        className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="5XX XXX XX XX"
                        required
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      TC Kimlik No <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="text"
                      inputMode="numeric"
                      pattern="[0-9]*"
                      value={formData.tc}
                      onChange={(e) => setFormData({ ...formData, tc: e.target.value.replace(/\D/g, '').slice(0, 11) })}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                      placeholder="11 haneli TC kimlik numaranız"
                      maxLength={11}
                      required
                    />
                    <p className="mt-2 text-xs text-gray-500 flex items-center gap-1">
                      <Shield className="w-3 h-3" />
                      TC kimlik numaranız iyzico güvenli ödeme sistemi tarafından istenmektedir
                    </p>
                  </div>

                  <button
                    onClick={handleNextStep}
                    className="w-full bg-black text-white py-4 rounded-lg font-medium hover:bg-gray-800 transition-all duration-300 hover:scale-105 active:scale-95"
                  >
                    Teslimat Bilgilerine Geç
                  </button>
                </div>
              )}

              {/* Step: Shipping */}
              {currentStep === 'shipping' && (
                <div className="space-y-6">
                  <div>
                    <h2 className="text-2xl font-bold text-black mb-2">Teslimat Adresi</h2>
                    <p className="text-gray-600 text-sm">Ürünlerinizin gönderileceği adresi belirtin</p>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Adres <span className="text-red-500">*</span>
                    </label>
                    <div className="relative">
                      <MapPin className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                      <textarea
                        value={formData.address}
                        onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                        className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="Mahalle, sokak, bina no, daire no"
                        rows={3}
                        required
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        İl <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        value={formData.city}
                        onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="İl"
                        required
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        İlçe <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        value={formData.district}
                        onChange={(e) => setFormData({ ...formData, district: e.target.value })}
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="İlçe"
                        required
                      />
          </div>
        </div>

        <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Posta Kodu (İsteğe bağlı)
                    </label>
                    <input
                      type="text"
                      value={formData.zipCode}
                      onChange={(e) => setFormData({ ...formData, zipCode: e.target.value })}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                      placeholder="34000"
                    />
                  </div>

                  {/* Shipping Method */}
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-3">
                      Kargo Seçimi
                    </label>
                    <div className="space-y-3">
                      <label className="flex items-center justify-between p-4 border-2 border-gray-200 rounded-lg cursor-pointer hover:border-black transition-all">
                        <div className="flex items-center gap-3">
                          <input
                            type="radio"
                            name="shipping"
                            value="standard"
                            checked={formData.shippingMethod === 'standard'}
                            onChange={(e) => setFormData({ ...formData, shippingMethod: e.target.value })}
                            className="w-4 h-4"
                          />
                          <div>
                            <div className="font-medium text-black">Bugün Kargoda</div>
                            <div className="text-sm text-gray-600">Siparişin bugün kargoya verilir</div>
                          </div>
                        </div>
                        <div className="font-medium">
                          {subtotalAfterCoupon >= FREE_SHIPPING_THRESHOLD_KURUS ? (
                            <span className="text-green-600">Ücretsiz</span>
                          ) : (
                            <span>₺100</span>
                          )}
                        </div>
                      </label>
                    </div>
                  </div>

                  <div className="flex gap-4">
                    <button
                      onClick={handlePreviousStep}
                      className="flex-1 bg-gray-100 text-black py-4 rounded-lg font-medium hover:bg-gray-200 transition-all duration-300"
                    >
                      Geri
                    </button>
                    <button
                      onClick={handleNextStep}
                      className="flex-1 bg-black text-white py-4 rounded-lg font-medium hover:bg-gray-800 transition-all duration-300 hover:scale-105 active:scale-95"
                    >
                      Ödeme Bilgilerine Geç
                    </button>
                  </div>
                </div>
              )}

              {/* Step: Payment */}
              {currentStep === 'payment' && (
                <div className="space-y-6">
                  <div>
                    <h2 className="text-2xl font-bold text-black mb-2">Ödeme Bilgileri</h2>
                    <p className="text-gray-600 text-sm">iyzico güvenli ödeme sistemi ile kart bilgilerinizi girin</p>
                  </div>

                  {/* iyzico Badge */}
                  <div className="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-200 rounded-lg p-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <div className="w-12 h-12 bg-white rounded-lg flex items-center justify-center shadow-sm">
                          <span className="text-xl font-bold text-blue-600">iyzico</span>
                        </div>
                        <div>
                          <p className="text-sm font-semibold text-gray-900">Güvenli Ödeme</p>
                          <p className="text-xs text-gray-600">256-bit SSL ile korunuyor</p>
                        </div>
                      </div>
                      <Shield className="w-8 h-8 text-blue-600" />
                    </div>
                  </div>

                  {/* Security Info */}
                  <div className="flex items-center gap-2 p-3 bg-green-50 border border-green-200 rounded-lg">
                    <Shield className="w-5 h-5 text-green-600" />
                    <span className="text-sm text-green-800">
                      Ödemeniz iyzico güvenli ödeme altyapısı ile işlenmektedir
                    </span>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Kart Üzerindeki İsim <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="text"
                      value={formData.cardName}
                      onChange={(e) => setFormData({ ...formData, cardName: e.target.value.toUpperCase() })}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                      placeholder="AD SOYAD"
                      required
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Kart Numarası <span className="text-red-500">*</span>
                    </label>
                    <div className="relative">
                      <CreditCard className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                      <input
                        type="text"
                        value={formData.cardNumber}
                        onChange={(e) => {
                          const value = e.target.value.replace(/\s/g, '').replace(/[^0-9]/g, '')
                          const formatted = value.match(/.{1,4}/g)?.join(' ') || value
                          setFormData({ ...formData, cardNumber: formatted })
                        }}
                        className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="1234 5678 9012 3456"
                        maxLength={19}
                        required
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-3 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        Ay <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        value={formData.expireMonth}
                        onChange={(e) => {
                          const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 2)
                          setFormData({ ...formData, expireMonth: value })
                        }}
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="MM"
                        maxLength={2}
                        required
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        Yıl <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        value={formData.expireYear}
                        onChange={(e) => {
                          const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 4)
                          setFormData({ ...formData, expireYear: value })
                        }}
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                        placeholder="YYYY"
                        maxLength={4}
                        required
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">
                        CVV <span className="text-red-500">*</span>
                      </label>
                      <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <input
                          type="text"
                          value={formData.cvc}
                          onChange={(e) => {
                            const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 3)
                            setFormData({ ...formData, cvc: value })
                          }}
                          className="w-full pl-9 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black focus:border-transparent transition-all"
                          placeholder="123"
                          maxLength={3}
                          required
                        />
                      </div>
                    </div>
                  </div>

                  {/* Terms */}
                  <div className="space-y-3 pt-4 border-t border-gray-200">
                    <label className="flex items-start gap-3 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={formData.termsAccepted}
                        onChange={(e) => setFormData({ ...formData, termsAccepted: e.target.checked })}
                        className="mt-1 w-4 h-4"
                        required
                      />
                      <span className="text-sm text-gray-700">
                        <Link href="/kullanim-kosullari" className="text-black underline hover:no-underline" target="_blank">
                          Kullanım Koşulları
                        </Link>
                        {' '}ve{' '}
                        <Link href="/gizlilik" className="text-black underline hover:no-underline" target="_blank">
                          Gizlilik Politikası
                        </Link>
                        'nı okudum, kabul ediyorum. <span className="text-red-500">*</span>
                      </span>
                    </label>

                    <label className="flex items-start gap-3 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={formData.kvkkAccepted}
                        onChange={(e) => setFormData({ ...formData, kvkkAccepted: e.target.checked })}
                        className="mt-1 w-4 h-4"
                        required
                      />
                      <span className="text-sm text-gray-700">
                        <Link href="/kvkk" className="text-black underline hover:no-underline" target="_blank">
                          KVKK Aydınlatma Metni
                        </Link>
                        'ni okudum, kişisel verilerimin işlenmesini kabul ediyorum. <span className="text-red-500">*</span>
                      </span>
                    </label>
                  </div>

                  <div className="flex gap-4">
                    <button
                      onClick={handlePreviousStep}
                      disabled={isProcessing}
                      className="flex-1 bg-gray-100 text-black py-4 rounded-lg font-medium hover:bg-gray-200 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Geri
                    </button>
                    <button
                      onClick={handlePayment}
                      disabled={paymentUncertain || isProcessing || isApplyingCoupon || !pricesVerified || !formData.termsAccepted || !formData.kvkkAccepted}
                      className="flex-1 bg-green-600 text-white py-4 rounded-lg font-medium hover:bg-green-700 transition-all duration-300 hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100"
                    >
                      {isProcessing ? 'İşleniyor...' : `₺${formatTRY(toDisplayPrice(total))} Öde`}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Order Summary - Sticky Sidebar */}
          <div className="lg:col-span-1">
            <div className="bg-white rounded-xl shadow-sm p-6 lg:sticky lg:top-24">
              <h3 className="text-lg font-bold text-black mb-4">Sipariş Özeti</h3>

              {/* Cart Items */}
              <div className="space-y-4 mb-6 max-h-64 overflow-y-auto">
                {cartItems.map((item) => (
                  <div key={item.id} className="flex gap-3">
                    <div className="relative w-16 h-16 bg-gray-100 rounded-lg overflow-hidden flex-shrink-0">
                      <ProductImage
                        src={item.image}
                        alt={item.name}
                        fill
                        sizes="64px"
                      />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium text-black line-clamp-2">{item.name}</h4>
                      <div className="flex items-center justify-between mt-1">
                        <span className="text-xs text-gray-500">Adet: {item.qty}</span>
                        <span className="text-sm font-medium text-black">
                          ₺{formatTRY(toDisplayPrice(item.price * item.qty))}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
          </div>

          {/* Price Breakdown */}
              <div className="border-t border-gray-200 pt-4 space-y-3">
                <div>
                  <label className="mb-2 block text-sm text-gray-700">Kupon Kodu</label>
                  <div className="flex gap-2">
                    <input
                      value={couponCode}
                      disabled={isApplyingCoupon || isProcessing}
                      onChange={(e) => {
                        setCouponCode(e.target.value.toUpperCase())
                        setCouponDiscount(0)
                        setValidatedCouponCode('')
                        clearAppliedCouponCode()
                      }}
                      className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
                      placeholder="KODUNUZU GİRİN"
                    />
                    <button
                      onClick={() => void applyCoupon()}
                      disabled={isApplyingCoupon || isProcessing}
                      className="rounded-lg bg-gray-900 px-3 py-2 text-sm text-white hover:bg-black disabled:opacity-60"
                    >
                      {isApplyingCoupon ? '...' : 'Uygula'}
                    </button>
                  </div>
                  {couponError && <p className="mt-2 text-xs text-red-600">{couponError}</p>}
                </div>

                <div className="flex justify-between text-sm">
                  <span className="text-gray-600">Ara Toplam</span>
                  <span className="font-medium text-black">₺{formatTRY(toDisplayPrice(subtotal))}</span>
            </div>

                {couponDiscount > 0 && (
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-600">Kupon İndirimi</span>
                    <span className="font-medium text-green-600">-₺{formatTRY(toDisplayPrice(couponDiscount))}</span>
                  </div>
                )}

                <div className="flex justify-between text-sm">
                  <span className="text-gray-600">
                    Kargo (Bugün Kargoda)
                  </span>
                  <span className={`font-medium ${shipping === 0 ? 'text-green-600' : 'text-black'}`}>
                    {shipping === 0 ? 'Ücretsiz' : `₺${formatTRY(toDisplayPrice(shipping))}`}
              </span>
            </div>
            
            {/* Free Shipping Progress */}
                {subtotalAfterCoupon < FREE_SHIPPING_THRESHOLD_KURUS && formData.shippingMethod === 'standard' && (
                  <div className="pt-2">
                    <div className="text-xs text-orange-600 mb-2">
                  Ücretsiz kargo için ₺{formatTRY(toDisplayPrice(FREE_SHIPPING_THRESHOLD_KURUS - subtotalAfterCoupon))} daha ekleyin
                </div>
                    <div className="w-full bg-gray-200 rounded-full h-1.5">
                  <div 
                        className="bg-orange-500 h-1.5 rounded-full transition-all duration-500"
                    style={{ width: `${Math.min((subtotalAfterCoupon / FREE_SHIPPING_THRESHOLD_KURUS) * 100, 100)}%` }}
                      />
                </div>
              </div>
            )}

                <div className="flex justify-between text-base font-bold text-black pt-3 border-t border-gray-200">
              <span>Toplam</span>
                  <span>₺{formatTRY(toDisplayPrice(total))}</span>
            </div>
          </div>

              {/* Security Icons */}
              <div className="mt-6 pt-6 border-t border-gray-200 space-y-3">
                <div className="flex items-center justify-center gap-2 p-3 bg-blue-50 rounded-lg">
                  <span className="text-sm font-semibold text-blue-900">iyzico</span>
                  <span className="text-xs text-blue-700">ile güvenli ödeme</span>
                </div>
                <div className="flex items-center justify-center gap-4 text-xs text-gray-500">
                  <div className="flex items-center gap-1">
                    <Shield className="w-4 h-4" />
                    <span>Güvenli Ödeme</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Lock className="w-4 h-4" />
                    <span>SSL Korumalı</span>
                  </div>
                </div>
              </div>
            </div>
        </div>
      </div>
      </div>

      <Footer />
    </div>
  )
}
